package com.spai.portal.asset.domain;
import java.time.OffsetDateTime;import javax.persistence.*;
@Entity @Table(name="file_object") public class FileObject {@Id private String id;@Column(name="gridfs_id",nullable=false,unique=true)private String gridfsId;@Column(name="file_name",nullable=false)private String fileName;@Column(name="content_type")private String contentType;@Column(name="file_size",nullable=false)private long fileSize;@Column(nullable=false,length=64)private String sha256;@Column(nullable=false)private String status="ACTIVE";@Column(name="created_at",nullable=false)private OffsetDateTime createdAt=OffsetDateTime.now();public String getId(){return id;}public void setId(String id){this.id=id;}public String getGridfsId(){return gridfsId;}public void setGridfsId(String gridfsId){this.gridfsId=gridfsId;}public String getFileName(){return fileName;}public void setFileName(String fileName){this.fileName=fileName;}public String getContentType(){return contentType;}public void setContentType(String contentType){this.contentType=contentType;}public long getFileSize(){return fileSize;}public void setFileSize(long fileSize){this.fileSize=fileSize;}public String getSha256(){return sha256;}public void setSha256(String sha256){this.sha256=sha256;}public String getStatus(){return status;}public void setStatus(String status){this.status=status;}public OffsetDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(OffsetDateTime createdAt){this.createdAt=createdAt;}}
